// Type declarations for the kofem_wasm WebAssembly module.
// The actual .js/.wasm files are generated by scripts/build-wasm.sh and are gitignored.

/** Tessellated STEP surface returned as flat typed arrays (binary, no JSON text).
 *  `vertices` is xyz interleaved (length 3·nVerts); `triangles` is three 0-based
 *  vertex indices per triangle (length 3·nTris); `triangleBodyIds` is the
 *  1-based body (CAD solid) index of each triangle (length nTris), matching the
 *  body ids of the volume mesh (issue #353) for per-body colour / highlight /
 *  hide in the geometry view. `bodyCount` is the number of solids in the
 *  imported shape — 0 when the file held no closed solid (surface-only
 *  geometry that failed sewing). */
export interface StepTessellation {
  vertices: Float32Array
  triangles: Uint32Array
  triangleBodyIds: Uint32Array
  bodyCount: number
}

/** FEM volume mesh returned as flat typed arrays (binary, no JSON text — issue #166).
 *  `vertices` is xyz interleaved (length 3·nNodes); `tetrahedra` is four 0-based
 *  vertex indices per tet (length 4·nTets); `bodyIds` is the 1-based body
 *  (CAD solid) index of each tet (issue #353); `surfaceTriangles` is three
 *  0-based vertex indices per boundary triangle; `surfaceFaceIds` is the 1-based
 *  OCC face index of each boundary triangle (one entry per triangle). */
export interface FemMesh {
  vertices: Float64Array
  tetrahedra: Int32Array
  bodyIds: Int32Array
  surfaceTriangles: Int32Array
  surfaceFaceIds: Int32Array
}

/** Volume-mesh input to the solver: flat typed arrays, same layout as FemMesh.
 *  `hexahedra` is eight 0-based vertex indices per hex and may be omitted.
 *  `attributes` is one 1-based material index per element (tets first, then
 *  hexs) for multi-material models (issue #353); omitted means every element
 *  uses material 1. */
export interface SolveMesh {
  vertices: Float64Array
  tetrahedra: Int32Array
  hexahedra?: Int32Array
  attributes?: Int32Array
}

/** Solve output as flat typed arrays: three displacement components per vertex
 *  (length 3·nNodes) and one von Mises value per element (length nElems).
 *  Incomplete material inputs yield `{error}` instead (issue #344). */
export type StaticSolveResult =
  | { displacements: Float64Array; von_mises: Float64Array }
  | { error: string }

/** Triangle SURFACE mesh input to the Kirchhoff shell solver: `vertices` is xyz
 *  interleaved (length 3·nNodes); `triangles` is three 0-based vertex indices
 *  per triangle (length 3·nTris). `thicknesses` is an optional per-triangle
 *  thickness field (length nTris) for walls of differing gauge; when omitted the
 *  scalar thickness in the material JSON is used. */
export interface ShellMesh {
  vertices: Float64Array
  triangles: Int32Array
  thicknesses?: Float64Array
}

/** Shell solve output: three translation components (u,v,w) per vertex
 *  (length 3·nNodes). Bad input / non-convergence yields `{error}` instead. */
export type ShellSolveResult =
  | { displacements: Float64Array }
  | { error: string }

/** Runtime interface of the initialised Emscripten/Embind module. */
export interface KofemModule {
  /** Load a STEP or IGES file and tessellate it for display.
   *  @param cad_bytes Raw STEP/IGES file bytes.
   *  @param opts_json JSON `{ deflection_relative?, linear_deflection?, angular_deflection?, format?: "step" | "iges" }`.
   *                   `format` selects the reader (defaults to "step").
   */
  tessellate_step(cad_bytes: Uint8Array, opts_json: string): StepTessellation
  tessellate_for_meshing(opts_json: string): string
  generate_volume_mesh(surface_json: string, opts_json: string): string
  /** Generate a FEM surface mesh + volume mesh directly from the stored STEP geometry
   *  using Netgen's native OCC integration.  Must call tessellate_step first.
   *  @param opts_json JSON `{ max_element_size, min_element_size, grading, second_order, elementsperedge, elementspercurve, optsteps_2d, optsteps_3d }`
   */
  generate_fem_mesh(opts_json: string): FemMesh
  /** Release the OCCT shape + STEP byte cache from WASM heap.
   *  Call this after meshing is complete and before solving to free ~10–30 MB
   *  of WASM memory that is no longer needed.
   */
  free_geometry_cache(): void
  /** Linear-elastic solve. The mesh crosses the boundary as flat typed arrays;
   *  materials and boundary conditions stay JSON (small payloads). `mat_json`
   *  is an array of materials — `mesh.attributes` selects per element, 1-based —
   *  or a single material object (legacy single-material contract). */
  solve_linear_elastic(
    mesh: SolveMesh,
    mat_json: string,
    bcs_json: string,
    order: number,
  ): StaticSolveResult
  /** Kirchhoff flat-facet shell solve on a triangle surface mesh. `mat_json` is
   *  `{ young_modulus, poisson_ratio, thickness }`; `bcs_json` is
   *  `{ fixed_vertices?, fixed_dofs?, point_loads? }` with DOF components
   *  0..5 = (u,v,w,θx,θy,θz). Returns three translations per node. */
  solve_shell(
    mesh: ShellMesh,
    mat_json: string,
    bcs_json: string,
  ): ShellSolveResult
  /** Coupled solid(tet)+shell solve. MFEM assembles the solid; DKT shells and
   *  RBE3 distributing couplings are added and solved together.
   *   mesh:     { vertices, tets, triangles, thicknesses? }
   *   coupling: { ref, offsets, solid }  CSR-style: reference node ref[k] ties to
   *             solid[offsets[k]..offsets[k+1]).
   *   bcs:      { fixed_dofs, load_dofs, load_vals }  (DOF = 6·node+component)
   *   mat_json: { solid:{young_modulus,poisson_ratio}, shell:{…} } */
  solve_coupled(
    mesh: {
      vertices: Float64Array
      tets: Int32Array
      triangles: Int32Array
      thicknesses?: Float64Array
    },
    coupling: { ref: Int32Array; offsets: Int32Array; solid: Int32Array },
    bcs: { fixed_dofs: Int32Array; load_dofs: Int32Array; load_vals: Float64Array },
    mat_json: string,
  ): { displacements: Float64Array; iterations: number } | { error: string }
}

export interface ModuleOverrides {
  print?: (text: string) => void
  printErr?: (text: string) => void
  wasmBinary?: ArrayBuffer
}

/** Initialise the WASM module and return it. Must be awaited before using any function. */
export default function init(overrides?: ModuleOverrides): Promise<KofemModule>
